 FleetDamageState state;state.bind_context(&profile,1,1,0x10000,0x20000,0x30000);CHECK(state.transfer_count()==2&&state.max_transfer_distance()==.01f);
 CHECK(state.observe(0,g,source,false,0x500,7));
 auto damaged=g;const float moved[3][3]={{1,0,0},{1,2,0},{0,1,4}};for(unsigned v=0;v<3;++v)std::memcpy(damaged.vertex_bytes.data()+v*24,moved[v],12);
